:root {
    --background: #f3f6f8;
    --surface: #ffffff;
    --text: #17212b;
    --muted-text: #637180;
    --border: #d6dee5;
    --accent: #176b87;
    --accent-hover: #12566d;
    --danger: #a33a3a;
    --completed: #7a8791;
    --shadow: 0 12px 30px rgba(28, 48, 64, 0.08);
}

* {
    box-sizing: border-box;
}

body {
    margin: 0;
    min-width: 320px;
    min-height: 100vh;
    background: var(--background);
    color: var(--text);
    font-family: Georgia, "Times New Roman", serif;
}

button,
input {
    font: inherit;
}

button {
    border: 0;
    cursor: pointer;
}

.todo-app {
    width: min(100% - 2rem, 700px);
    margin: 0 auto;
    padding: 4rem 0;
}

.app-header {
    margin-bottom: 2rem;
}

.eyebrow {
    margin: 0 0 0.5rem;
    color: var(--accent);
    font-family: Arial, sans-serif;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

h1,
h2,
p {
    margin-top: 0;
}

h1 {
    margin-bottom: 0.5rem;
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    line-height: 1;
}

.subtitle {
    margin-bottom: 0;
    color: var(--muted-text);
    font-size: 1.1rem;
}

.todo-panel {
    padding: clamp(1.25rem, 4vw, 2rem);
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    box-shadow: var(--shadow);
}

h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

.todo-form label {
    display: block;
    margin-bottom: 0.5rem;
    font-family: Arial, sans-serif;
    font-size: 0.875rem;
    font-weight: 700;
}

.input-row {
    display: flex;
    gap: 0.75rem;
}

#todoInput {
    min-width: 0;
    flex: 1;
    padding: 0.8rem 0.9rem;
    color: var(--text);
    border: 1px solid var(--border);
    border-radius: 4px;
    background: #fbfcfd;
}

#todoInput:focus {
    outline: 3px solid rgba(23, 107, 135, 0.2);
    border-color: var(--accent);
}

#addButton,
.complete-button,
.delete-button,
#clearButton {
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-family: Arial, sans-serif;
    font-size: 0.875rem;
    font-weight: 700;
}

#addButton {
    color: #ffffff;
    background: var(--accent);
}

#addButton:hover {
    background: var(--accent-hover);
}

.error-message {
    min-height: 1.4em;
    margin: 1rem 0 0;
    color: var(--danger);
    font-family: Arial, sans-serif;
    font-size: 0.875rem;
}

.todo-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    min-height: 4rem;
    margin: 0;
    padding: 0;
    list-style: none;
}

.todo-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem;
    border: 1px solid var(--border);
    border-radius: 4px;
}

.todo-item-name {
    flex: 1;
    overflow-wrap: anywhere;
}

.todo-item.completed .todo-item-name {
    color: var(--completed);
    text-decoration: line-through;
}

.complete-button {
    color: var(--accent);
    background: #e9f3f6;
}

.delete-button {
    color: var(--danger);
    background: #f9eeee;
}

.list-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin-top: 1.25rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--border);
}

.task-count {
    color: var(--muted-text);
    font-family: Arial, sans-serif;
    font-size: 0.875rem;
}

#clearButton {
    color: var(--muted-text);
    background: transparent;
    border: 1px solid var(--border);
}

#clearButton:hover {
    color: var(--text);
    border-color: var(--muted-text);
}

@media (max-width: 480px) {
    .todo-app {
        padding: 2.5rem 0;
    }

    .input-row {
        flex-direction: column;
    }

    #addButton {
        width: 100%;
    }

    .todo-item {
        align-items: flex-start;
        flex-wrap: wrap;
    }

    .todo-item-name {
        flex-basis: calc(100% - 2rem);
    }
}

